#!/usr/bin/env python3
"""
Automatisk generert av generate.py (loginfix) - IKKE rediger denne filen direkte.

Fikser innlogging som kunne henge, utvider sesjonen til 30 dager, og legger til
en 'Glemt passord?'-knapp som varsler andre administratorer overst pa alle sider.

Idempotent: hvert steg hopper over seg selv hvis allerede gjort.
Kjor fra prosjektroten: python3 scripts/deploy_login_fixes.py
"""
import pathlib
import subprocess
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent

ok = True

def apply_edit(path, old, new, marker, label):
    global ok
    text = path.read_text()
    if marker in text:
        print(f"[already done] {label}")
        return
    if text.count(old) != 1:
        print(f"[SKIPPED - ikke funnet/entydig] {label}")
        ok = False
        return
    path.write_text(text.replace(old, new, 1))
    print(f"[OK] {label}")

def write_full(path, content, marker, label):
    global ok
    if path.exists() and marker in path.read_text():
        print(f"[already done] {label}")
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content)
    print(f"[OK] {label}")

SESSION_PATH = ROOT / 'lib' / 'auth' / 'session.ts'
apply_edit(SESSION_PATH, 'export const SESSION_MAX_AGE_SECONDS = 60 * 60 * 24 * 7; // 7 dager', 'export const SESSION_MAX_AGE_SECONDS = 60 * 60 * 24 * 30; // 30 dager ("husk meg" - var 7 dager tidligere)', '60 * 60 * 24 * 30', 'session-maxage')

MIDDLEWARE_PATH = ROOT / 'middleware.ts'
apply_edit(MIDDLEWARE_PATH, 'const BOOKINGS_ONLY_ALLOWED_API_EXACT = new Set([\n  "/api/admin/me",\n  "/api/admin/logout",\n  "/api/admin/block",\n  "/api/admin/account/password",\n]);', 'const BOOKINGS_ONLY_ALLOWED_API_EXACT = new Set([\n  "/api/admin/me",\n  "/api/admin/logout",\n  "/api/admin/block",\n  "/api/admin/account/password",\n  // En begrenset administrator bør også få vite at en kollega har glemt\n  // passordet sitt - se app/admin/AdminNav.tsx og\n  // lib/settings/passwordResetNotice.ts.\n  "/api/admin/password-reset-notice",\n]);', 'password-reset-notice', 'mw-bookingsonly-exact')
apply_edit(MIDDLEWARE_PATH, '  const isAdminApi = pathname.startsWith("/api/admin") && pathname !== "/api/admin/login";', '  // "/api/admin/forgot-password" er offentlig på nøyaktig samme måte som\n  // "/api/admin/login" - den kalles jo fra innloggingssiden, FØR man er\n  // logget inn (se LoginForm.tsx).\n  const isAdminApi =\n    pathname.startsWith("/api/admin") &&\n    pathname !== "/api/admin/login" &&\n    pathname !== "/api/admin/forgot-password";', '"/api/admin/forgot-password";', 'mw-public-forgot-password')

LOGINFORM_PATH = ROOT / 'app' / 'admin' / 'login' / 'LoginForm.tsx'
apply_edit(LOGINFORM_PATH, 'import { useState, type FormEvent } from "react";\nimport { useRouter, useSearchParams } from "next/navigation";\nimport styles from "../admin.module.css";\n\nexport default function LoginForm() {\n  const router = useRouter();\n  const searchParams = useSearchParams();\n  const next = searchParams.get("next") || "/admin";\n\n  const [email, setEmail] = useState("");\n  const [password, setPassword] = useState("");\n  const [error, setError] = useState<string | null>(null);\n  const [submitting, setSubmitting] = useState(false);', 'import { useState, type FormEvent } from "react";\nimport { useSearchParams } from "next/navigation";\nimport styles from "../admin.module.css";\n\nexport default function LoginForm() {\n  const searchParams = useSearchParams();\n  const next = searchParams.get("next") || "/admin";\n\n  const [email, setEmail] = useState("");\n  const [password, setPassword] = useState("");\n  const [error, setError] = useState<string | null>(null);\n  const [submitting, setSubmitting] = useState(false);\n\n  // --- "Glemt passord?" - varsler de andre administratorene (se\n  // app/admin/AdminNav.tsx + app/api/admin/forgot-password/route.ts), i\n  // stedet for en ekte selvbetjent tilbakestilling (appen har ingen\n  // e-posttjeneste å sende en lenke med). ---\n  const [showForgotPassword, setShowForgotPassword] = useState(false);\n  const [sendingForgotPassword, setSendingForgotPassword] = useState(false);\n  const [forgotPasswordMessage, setForgotPasswordMessage] = useState<string | null>(null);\n\n  async function handleForgotPassword() {\n    if (!email.trim() || !email.includes("@")) {\n      setForgotPasswordMessage("Skriv inn e-posten din i feltet over først.");\n      return;\n    }\n\n    setSendingForgotPassword(true);\n    setForgotPasswordMessage(null);\n    try {\n      await fetch("/api/admin/forgot-password", {\n        method: "POST",\n        headers: { "Content-Type": "application/json" },\n        body: JSON.stringify({ email }),\n      });\n      setForgotPasswordMessage("De andre administratorene er varslet, hvis e-posten tilhører en admin-bruker.");\n    } catch {\n      setForgotPasswordMessage("Kunne ikke sende varsel akkurat nå. Prøv igjen senere.");\n    } finally {\n      setSendingForgotPassword(false);\n    }\n  }', 'handleForgotPassword() {', 'lf-imports-and-state')
apply_edit(LOGINFORM_PATH, '      router.push(next);\n      router.refresh();', '      // Hard navigasjon (IKKE router.push + router.refresh): sikrer at den\n      // nye sesjonscookien faktisk er med i forespørselen som laster "next"-\n      // siden, slik at middleware.ts ser den med en gang. Med bare\n      // client-side-navigasjon kunne siden bli hengende på "Logger inn …"\n      // til man oppdaterte siden manuelt.\n      window.location.href = next;', 'Hard navigasjon (IKKE router.push', 'lf-hard-navigation')
apply_edit(LOGINFORM_PATH, '      {error && <p className={styles.error}>{error}</p>}\n      <button type="submit" className={styles.submitButton} disabled={submitting}>\n        {submitting ? "Logger inn …" : "Logg inn"}\n      </button>\n    </form>\n  );\n}', '      {error && <p className={styles.error}>{error}</p>}\n      <button type="submit" className={styles.submitButton} disabled={submitting}>\n        {submitting ? "Logger inn …" : "Logg inn"}\n      </button>\n\n      <button\n        type="button"\n        className={styles.secondaryButton}\n        style={{ marginTop: 10 }}\n        onClick={() => {\n          setShowForgotPassword((v) => !v);\n          setForgotPasswordMessage(null);\n        }}\n      >\n        Glemt passord?\n      </button>\n\n      {showForgotPassword && (\n        <div className={styles.formRow} style={{ marginTop: 10 }}>\n          <p className={styles.bookingMeta}>\n            Vi har ingen automatisk tilbakestilling – trykk under for å varsle de andre administratorene,\n            så kan en av dem sette et nytt passord for deg under Administratorer.\n          </p>\n          <button\n            type="button"\n            className={styles.submitButton}\n            onClick={handleForgotPassword}\n            disabled={sendingForgotPassword}\n          >\n            {sendingForgotPassword ? "Sender …" : "Send varsel til administratorene"}\n          </button>\n          {forgotPasswordMessage && <p className={styles.bookingMeta}>{forgotPasswordMessage}</p>}\n        </div>\n      )}\n    </form>\n  );\n}', 'Send varsel til administratorene', 'lf-jsx-forgot-password')

ADMINNAV_PATH = ROOT / 'app' / 'admin' / 'AdminNav.tsx'
apply_edit(ADMINNAV_PATH, 'interface Me {\n  name: string;\n  email: string;\n  role?: string;\n}', 'interface Me {\n  name: string;\n  email: string;\n  role?: string;\n}\n\n/** Se lib/settings/passwordResetNotice.ts. */\ninterface PasswordResetNotice {\n  name: string;\n  email: string;\n  requestedAt: string;\n}', 'interface PasswordResetNotice {', 'nav-imports-and-interface')
apply_edit(ADMINNAV_PATH, 'export default function AdminNav({ active }: { active: AdminNavKey }) {\n  const [me, setMe] = useState<Me | null>(null);\n\n  useEffect(() => {\n    fetch("/api/admin/me", { cache: "no-store" })\n      .then((res) => (res.ok ? (res.json() as Promise<Me>) : null))\n      .then((data) => {\n        if (data) setMe(data);\n      })\n      .catch(() => {\n        // Ikke kritisk – i verste fall vises alle menypunktene kortvarig for\n        // en begrenset admin; middleware.ts stenger fortsatt det hun/han\n        // ikke har tilgang til om et slikt menypunkt faktisk klikkes på.\n      });\n  }, []);', 'export default function AdminNav({ active }: { active: AdminNavKey }) {\n  const [me, setMe] = useState<Me | null>(null);\n\n  // "Noen har glemt passordet sitt"-varselet (se app/admin/login/LoginForm.tsx\n  // + app/api/admin/forgot-password/route.ts) - hentes her siden AdminNav\n  // rendres øverst på absolutt alle innloggede admin-sider, uavhengig av\n  // hvilken fane man står på.\n  const [notice, setNotice] = useState<PasswordResetNotice | null>(null);\n  const [dismissingNotice, setDismissingNotice] = useState(false);\n\n  useEffect(() => {\n    fetch("/api/admin/me", { cache: "no-store" })\n      .then((res) => (res.ok ? (res.json() as Promise<Me>) : null))\n      .then((data) => {\n        if (data) setMe(data);\n      })\n      .catch(() => {\n        // Ikke kritisk – i verste fall vises alle menypunktene kortvarig for\n        // en begrenset admin; middleware.ts stenger fortsatt det hun/han\n        // ikke har tilgang til om et slikt menypunkt faktisk klikkes på.\n      });\n\n    fetch("/api/admin/password-reset-notice", { cache: "no-store" })\n      .then((res) => (res.ok ? (res.json() as Promise<{ notice: PasswordResetNotice | null }>) : null))\n      .then((data) => setNotice(data?.notice ?? null))\n      .catch(() => {\n        // Ikke kritisk – varselet er bare en hyggelig ekstra-ting, ikke noe\n        // sikkerhetskritisk å garantere leveranse av.\n      });\n  }, []);\n\n  async function handleDismissNotice() {\n    setDismissingNotice(true);\n    try {\n      await fetch("/api/admin/password-reset-notice", { method: "DELETE" });\n      setNotice(null);\n    } finally {\n      setDismissingNotice(false);\n    }\n  }', 'async function handleDismissNotice() {', 'nav-state-and-fetch')
apply_edit(ADMINNAV_PATH, '  return (\n    <>\n      <div className={styles.sidebar}>', '  return (\n    <>\n      {notice && (\n        <div className={styles.passwordResetBanner}>\n          <span>\n            <strong>{notice.name}</strong> ({notice.email}) har glemt passordet sitt – sett et nytt for dem under\n            Administratorer.\n          </span>\n          <button type="button" onClick={handleDismissNotice} disabled={dismissingNotice}>\n            {dismissingNotice ? "Fjerner …" : "Lukk"}\n          </button>\n        </div>\n      )}\n\n      <div className={styles.sidebar}>', 'styles.passwordResetBanner', 'nav-render-banner')

CSS_PATH = ROOT / 'app' / 'admin' / 'admin.module.css'
apply_edit(CSS_PATH, '.sidebar {\n  position: fixed;\n  top: 0;\n  left: 0;\n  bottom: 0;\n  width: 232px;\n  background: var(--available);\n  border-right: 1px solid var(--border);\n  display: flex;\n  flex-direction: column;\n  overflow-y: auto;\n  z-index: 40;\n}', '.passwordResetBanner {\n  position: fixed;\n  top: 0;\n  left: 0;\n  right: 0;\n  z-index: 100;\n  min-height: 40px;\n  padding: 8px 16px;\n  background: var(--brand-yellow);\n  color: var(--ink);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 16px;\n  flex-wrap: wrap;\n  font-size: 0.9rem;\n  text-align: center;\n}\n\n.passwordResetBanner button {\n  padding: 4px 10px;\n  border: 1px solid var(--ink);\n  border-radius: 6px;\n  background: transparent;\n  color: var(--ink);\n  cursor: pointer;\n  font-size: 0.85rem;\n}\n\n/* Skyver den faste sidemenyen/toppbaren ned mens varselet vises, slik at det\n   ikke dekker over "Adminpanel"-merket/profilmenyen - se AdminNav.tsx. */\nbody:has(.passwordResetBanner) .sidebar,\nbody:has(.passwordResetBanner) .topBar {\n  top: 40px;\n}\n\n.sidebar {\n  position: fixed;\n  top: 0;\n  left: 0;\n  bottom: 0;\n  width: 232px;\n  background: var(--available);\n  border-right: 1px solid var(--border);\n  display: flex;\n  flex-direction: column;\n  overflow-y: auto;\n  z-index: 40;\n}', '.passwordResetBanner {', 'css-password-reset-banner')

write_full(ROOT / 'lib' / 'settings' / 'passwordResetNotice.ts', 'import "server-only";\nimport { getRepository } from "@/lib/db";\n\n/**\n * "Noen har glemt passordet sitt"-varselet som vises øverst på alle\n * admin-sider (se app/admin/AdminNav.tsx) etter at noen trykker "Glemt\n * passord?" på innloggingssiden (se app/admin/login/LoginForm.tsx +\n * app/api/admin/forgot-password/route.ts).\n *\n * Bevisst KUN ett varsel av gangen (ikke en liste/kø) – en delt "oppslagstavle"-\n * melding som HVEM SOM HELST innlogget administrator kan lukke, ikke en\n * personlig "ulest"-status per administrator. Lagret som JSON i den samme\n * generiske nøkkel/verdi-innstillingstabellen som resten av appen (se\n * lib/settings/pricing.ts for samme mønster) – ingen egen databasetabell\n * nødvendig for noe så enkelt som dette.\n */\nconst NOTICE_KEY = "pendingPasswordResetNotice";\n\nexport interface PasswordResetNotice {\n  name: string;\n  email: string;\n  /** ISO-8601-tidspunkt. */\n  requestedAt: string;\n}\n\nexport async function getPasswordResetNotice(): Promise<PasswordResetNotice | null> {\n  const repo = await getRepository();\n  const raw = await repo.getSetting(NOTICE_KEY);\n  if (!raw) return null;\n  try {\n    return JSON.parse(raw) as PasswordResetNotice;\n  } catch {\n    return null;\n  }\n}\n\nexport async function setPasswordResetNotice(notice: PasswordResetNotice): Promise<void> {\n  const repo = await getRepository();\n  await repo.setSetting(NOTICE_KEY, JSON.stringify(notice));\n}\n\nexport async function clearPasswordResetNotice(): Promise<void> {\n  const repo = await getRepository();\n  await repo.setSetting(NOTICE_KEY, "");\n}\n', 'export async function clearPasswordResetNotice', 'ny fil: lib/settings/passwordResetNotice.ts')
write_full(ROOT / 'app' / 'api' / 'admin' / 'forgot-password' / 'route.ts', 'import { NextRequest, NextResponse } from "next/server";\nimport { getRepository } from "@/lib/db";\nimport { setPasswordResetNotice } from "@/lib/settings/passwordResetNotice";\n\nexport const dynamic = "force-dynamic";\n\ninterface Body {\n  email?: string;\n}\n\n/**\n * POST /api/admin/forgot-password\n *\n * Offentlig (ingen innlogging kreves – kalles fra innloggingssiden, se\n * LoginForm.tsx) – unntatt fra middleware.ts sin ellers strenge "krever\n * gyldig sesjon"-sjekk for /api/admin/**, på nøyaktig samme måte som\n * /api/admin/login selv.\n *\n * Lagrer et varsel (navn + e-post + tidspunkt) som vises øverst på ALLE\n * admin-sider for andre innloggede administratorer (se AdminNav.tsx +\n * lib/settings/passwordResetNotice.ts), helt til noen trykker bort det der.\n *\n * Svarer med samme generiske suksessmelding uansett om e-posten faktisk\n * tilhører en admin-bruker eller ikke – akkurat som /api/admin/login sin\n * "Feil e-post eller passord"-feil er lik uansett årsak – slik at\n * innloggingssiden ikke kan brukes til å sjekke hvilke e-postadresser som\n * finnes som admin-brukere.\n */\nexport async function POST(request: NextRequest) {\n  let body: Body;\n  try {\n    body = (await request.json()) as Body;\n  } catch {\n    return NextResponse.json({ error: "Ugyldig forespørsel." }, { status: 400 });\n  }\n\n  const email = body.email?.trim().toLowerCase() ?? "";\n\n  if (email && email.includes("@")) {\n    try {\n      const repo = await getRepository();\n      const user = await repo.getAdminByEmail(email);\n      if (user) {\n        await setPasswordResetNotice({\n          name: user.name,\n          email: user.email,\n          requestedAt: new Date().toISOString(),\n        });\n      }\n    } catch (err) {\n      console.error("[forgot-password] kunne ikke lagre varsel:", err);\n    }\n  }\n\n  return NextResponse.json({\n    ok: true,\n    message: "Hvis e-posten tilhører en administrator, er de andre administratorene varslet.",\n  });\n}\n', 'POST /api/admin/forgot-password', 'ny fil: app/api/admin/forgot-password/route.ts')
write_full(ROOT / 'app' / 'api' / 'admin' / 'password-reset-notice' / 'route.ts', 'import { NextResponse } from "next/server";\nimport { getPasswordResetNotice, clearPasswordResetNotice } from "@/lib/settings/passwordResetNotice";\n\nexport const dynamic = "force-dynamic";\n\n/**\n * GET    /api/admin/password-reset-notice – hent dagens "noen har glemt\n *        passordet sitt"-varsel (eller null hvis ingen venter), vist øverst\n *        på alle admin-sider av AdminNav.tsx.\n * DELETE /api/admin/password-reset-notice – fjern varselet. Hvem som helst\n *        innlogget kan fjerne det – det er en delt beskjed, ikke noe\n *        personlig per administrator.\n *\n * Tilgjengelig for BÅDE "full" og "bookings_only"-administratorer (se\n * BOOKINGS_ONLY_ALLOWED_API_EXACT i middleware.ts) – en begrenset\n * administrator bør også få vite at en kollega har glemt passordet sitt.\n */\nexport async function GET() {\n  const notice = await getPasswordResetNotice();\n  return NextResponse.json({ notice });\n}\n\nexport async function DELETE() {\n  await clearPasswordResetNotice();\n  return NextResponse.json({ ok: true });\n}\n', 'export async function DELETE', 'ny fil: app/api/admin/password-reset-notice/route.ts')

if not ok:
    print("\nEtt eller flere steg feilet - avbryter FOR typecheck (ingenting antas trygt).")
    sys.exit(1)

print("\nKjorer typecheck ...")
result = subprocess.run(["npm", "run", "typecheck"], cwd=ROOT)
if result.returncode == 0:
    print("\nTYPECHECK OK")
else:
    print("\nTYPECHECK FEILET")
    sys.exit(1)
